-- Point 6A — Encaissement industriel. Paiement != impression; CDF/USD séparés; mensualités séquentielles.
CREATE TABLE IF NOT EXISTS finance_cash_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,membership_id uuid NOT NULL REFERENCES school_memberships(id),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,status varchar(12) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','CLOSED')),UNIQUE(school_id,membership_id,status));
CREATE TABLE IF NOT EXISTS finance_charges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,enrollment_id uuid NOT NULL REFERENCES enrollments(id),label varchar(180) NOT NULL,currency varchar(3) NOT NULL CHECK(currency IN('CDF','USD')),net_amount numeric(18,2) NOT NULL CHECK(net_amount>=0),paid_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0 AND paid_amount<=net_amount),periodicity varchar(16) NOT NULL DEFAULT 'ONE_OFF' CHECK(periodicity IN('ONE_OFF','MONTHLY')),period_label varchar(32),period_order smallint,due_date date,status varchar(12) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','CANCELLED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_finance_charges_due ON finance_charges(school_id,enrollment_id,status,currency,period_order);
CREATE TABLE IF NOT EXISTS finance_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,enrollment_id uuid NOT NULL REFERENCES enrollments(id),cash_session_id uuid NOT NULL REFERENCES finance_cash_sessions(id),actor_user_id uuid NOT NULL REFERENCES users(id),amount numeric(18,2) NOT NULL CHECK(amount>0),currency varchar(3) NOT NULL CHECK(currency IN('CDF','USD')),receipt_number varchar(64) NOT NULL,idempotency_key varchar(180) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,receipt_number),UNIQUE(school_id,idempotency_key));
CREATE TABLE IF NOT EXISTS finance_payment_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES schools(id) ON DELETE CASCADE,payment_id uuid NOT NULL REFERENCES finance_payments(id),charge_id uuid NOT NULL REFERENCES finance_charges(id),amount numeric(18,2) NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(school_id,payment_id,charge_id));
ALTER TABLE finance_cash_sessions ENABLE ROW LEVEL SECURITY; ALTER TABLE finance_cash_sessions FORCE ROW LEVEL SECURITY;
ALTER TABLE finance_charges ENABLE ROW LEVEL SECURITY; ALTER TABLE finance_charges FORCE ROW LEVEL SECURITY;
ALTER TABLE finance_payments ENABLE ROW LEVEL SECURITY; ALTER TABLE finance_payments FORCE ROW LEVEL SECURITY;
ALTER TABLE finance_payment_allocations ENABLE ROW LEVEL SECURITY; ALTER TABLE finance_payment_allocations FORCE ROW LEVEL SECURITY;
DO $$ BEGIN
 CREATE POLICY finance_cash_sessions_tenant ON finance_cash_sessions USING (school_id=current_setting('app.school_id',true)::uuid) WITH CHECK(school_id=current_setting('app.school_id',true)::uuid);
 CREATE POLICY finance_charges_tenant ON finance_charges USING (school_id=current_setting('app.school_id',true)::uuid) WITH CHECK(school_id=current_setting('app.school_id',true)::uuid);
 CREATE POLICY finance_payments_tenant ON finance_payments USING (school_id=current_setting('app.school_id',true)::uuid) WITH CHECK(school_id=current_setting('app.school_id',true)::uuid);
 CREATE POLICY finance_alloc_tenant ON finance_payment_allocations USING (school_id=current_setting('app.school_id',true)::uuid) WITH CHECK(school_id=current_setting('app.school_id',true)::uuid);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
